    dgd_respiratory: "ਸਾਹ ਦੀ ਪ੍ਰਣਾਲੀ: ਵਿਚਕਾਰ ਇੱਕ ਨਾਲੀ ਜੋ ਦੋ ਸ਼ਾਖਾਵਾਂ ਵਿੱਚ ਵੰਡੀ ਜਾਂਦੀ ਹੈ, ਹਰ ਸ਼ਾਖਾ ਇੱਕ ਵੱਡੇ ਸਪੰਜੀ ਅੰਗ ਵਿੱਚ ਜਾਂਦੀ ਹੈ, ਸ਼ਾਖਾਵਾਂ ਦੇ ਸਿਰਿਆਂ ’ਤੇ ਬੁਲਬੁਲਿਆਂ ਦੇ ਨਿੱਕੇ ਗੁੱਛੇ, ਅਤੇ ਹੇਠਾਂ ਪੱਠਿਆਂ ਦਾ ਗੁੰਬਦ।",
