    h_respiratory_bronchus: "ਟ੍ਰੈਕੀਆ ਤੋਂ ਨਿਕਲਣ ਵਾਲੀਆਂ ਦੋ ਮੁੱਖ ਨਾਲੀਆਂ ਵਿੱਚੋਂ ਇੱਕ।",
    h_respiratory_bronchiole: "ਬ੍ਰੌਂਕਸ ਤੋਂ ਨਿਕਲਦੀ ਪਤਲੀ ਨਾਲੀ ਜੋ ਨਿੱਕੇ ਬੁਲਬੁਲਿਆਂ ’ਤੇ ਖ਼ਤਮ ਹੁੰਦੀ ਹੈ।",
    h_respiratory_lung: "ਸਪੰਜੀ ਅੰਗ ਜਿੱਥੇ ਆਕਸੀਜਨ ਖ਼ੂਨ ਵਿੱਚ ਦਾਖ਼ਲ ਹੁੰਦੀ ਹੈ।",
    h_respiratory_alveoli: "ਸੂਖਮ ਬੁਲਬੁਲੇ ਜਿਨ੍ਹਾਂ ਦੀਆਂ ਕੰਧਾਂ ਪਤਲੀਆਂ ਤੇ ਗਿੱਲੀਆਂ ਹੁੰਦੀਆਂ ਹਨ ਅਤੇ ਜਿੱਥੇ ਗੈਸਾਂ ਦਾ ਵਟਾਂਦਰਾ ਹੁੰਦਾ ਹੈ।",
    h_respiratory_diaphragm: "ਫੇਫੜਿਆਂ ਹੇਠਾਂ ਪੱਠਿਆਂ ਦੀ ਗੁੰਬਦ ਵਰਗੀ ਚਾਦਰ ਜੋ ਸਾਹ ਅੰਦਰ ਲੈਣ ਲਈ ਚਪਟੀ ਹੋ ਜਾਂਦੀ ਹੈ।",
    dg_circuit: "ਬਿਜਲਈ ਸਰਕਟ",
    dgd_circuit: "ਇੱਕ ਲੜੀਵਾਰ ਸਰਕਟ ਜਿਸ ਵਿੱਚ ਖੱਬੇ ਪਾਸੇ ਸੈੱਲ, ਉੱਪਰ ਸਵਿੱਚ ਅਤੇ ਰੋਧਕ, ਸੱਜੇ ਪਾਸੇ ਬੱਲਬ ਜਿਸ ਦੇ ਆਰ-ਪਾਰ ਇੱਕ ਮੀਟਰ ਲੱਗਾ ਹੈ, ਅਤੇ ਹੇਠਲੀ ਤਾਰ ਵਿੱਚ ਦੂਜਾ ਮੀਟਰ ਹੈ।",
    h_circuit_cell: "ਉਹ ਧੱਕਾ (ਵੋਲਟੇਜ ਅੰਤਰ) ਦਿੰਦਾ ਹੈ ਜੋ ਕਰੰਟ ਨੂੰ ਚਲਾਉਂਦਾ ਹੈ।",
    h_circuit_switch: "ਸਰਕਟ ਖੋਲ੍ਹ ਜਾਂ ਬੰਦ ਕਰ ਕੇ ਕਰੰਟ ਰੋਕਦਾ ਜਾਂ ਚਲਾਉਂਦਾ ਹੈ।",
    h_circuit_bulb: "ਬਿਜਲਈ ਊਰਜਾ ਨੂੰ ਰੌਸ਼ਨੀ ਦੇ ਰੂਪ ਵਿੱਚ ਟ੍ਰਾਂਸਫ਼ਰ ਕਰਦਾ ਹੈ।",
    h_circuit_resistor: "ਪੁਰਜ਼ਾ ਜੋ ਕਰੰਟ ਦੇ ਵਹਾਅ ਵਿੱਚ ਰੁਕਾਵਟ ਪਾਉਂਦਾ ਹੈ।",
    h_circuit_ammeter: "ਕਰੰਟ ਮਾਪਦਾ ਹੈ; ਲੜੀਵਾਰ ਲਾਇਆ ਜਾਂਦਾ ਹੈ।",
    h_circuit_voltmeter: "ਵੋਲਟੇਜ ਅੰਤਰ ਮਾਪਦਾ ਹੈ; ਪੁਰਜ਼ੇ ਦੇ ਆਰ-ਪਾਰ ਸਮਾਨਾਂਤਰ ਲਾਇਆ ਜਾਂਦਾ ਹੈ।",
