    h_eye_lens: "নমনীয় স্বচ্ছ চাকতি, যা আলোকে পেছনে সূক্ষ্মভাবে ফোকাস করে।",
    h_eye_retina: "আলো-সংবেদী স্তর, যাতে রড ও কোন কোষ থাকে।",
    "sc_h_eye_optic-nerve": "বৈদ্যুতিক সংকেত মস্তিষ্কে বয়ে নিয়ে যায়।",
    h_eye_ciliary: "পেশির বলয়, যা সংকুচিত বা শিথিল হয়ে সামনের চাকতির আকার বদলায়।",
    h_eye_suspensory: "তন্তু, যা ফোকাস করা চাকতিকে জায়গায় ধরে রাখে এবং টানে।",
    h_eye_sclera: "অক্ষিগোলকের শক্ত সাদা বাইরের আবরণ।",
    dg_heart: "মানুষের হৃৎপিণ্ড",
    dgd_heart: "চারটি প্রকোষ্ঠসহ একটি সরল হৃৎপিণ্ড, দুটি ওপরে ও দুটি নিচে, চারটি বড় রক্তনালি যা ঢুকছে ও বেরোচ্ছে, এবং ওপরের ও নিচের প্রকোষ্ঠের মাঝে দুটি কপাটিকা।",
    sc_dgn_heart: "হৃৎপিণ্ডটি সামনে থেকে দেখা অবস্থায় আঁকা: হৃৎপিণ্ডের ডান দিক ছবির বাম দিকে।",
    h_heart_ra: "ওপরের প্রকোষ্ঠ, যা শরীর থেকে অক্সিজেনহীন রক্ত গ্রহণ করে।",
    h_heart_la: "ওপরের প্রকোষ্ঠ, যা ফুসফুস থেকে অক্সিজেনযুক্ত রক্ত গ্রহণ করে।",
    h_heart_rv: "পাতলা দেয়ালের নিচের প্রকোষ্ঠ, যা ফুসফুসে রক্ত পাম্প করে।",
    h_heart_lv: "সবচেয়ে পুরু দেয়ালের প্রকোষ্ঠ; সারা শরীরে রক্ত পাম্প করে।",
    h_heart_aorta: "সবচেয়ে বড় ধমনি; অক্সিজেনযুক্ত রক্ত শরীরে বহন করে।",
    "sc_h_heart_vena-cava": "বড় শিরা, যা শরীর থেকে অক্সিজেনহীন রক্ত ফিরিয়ে আনে।",
